#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <omp.h>

#define N 1000000 // Number of intervals for integration

double calculate_pi_parallel_trapezoidal() {
    double integral = 0.0;
    double dx = 1.0 / N;

    #pragma omp parallel for reduction(+:integral)
    for (int i = 0; i < N; i++) {
        double x = (i + 0.5) * dx;
        double fx = sqrt(1.0 - x * x);
        integral += fx * dx;
    }

    return 4.0 * integral;
}

double integral_roundrobin() {
    double sum = 0.0;
    double dx = 1.0 / N;
    double step_size = 1.0 / N;
    double start = 0.0;
    double end = 1.0;
    double total_steps = end - start;

    #pragma omp parallel for reduction(+:sum)
    for (int i = 0; i < total_steps; i++) {
        double x_start = start + i * step_size;
        double x_end = x_start + step_size;
        double mid_x = (x_start + x_end) / 2.0;
        double fx_start = sqrt(1.0 - x_start * x_start);
        double fx_end = sqrt(1.0 - x_end * x_end);
        double area = (x_end - x_start) * (fx_start + fx_end) / 2.0;
        sum += area;
    }

    return 4.0 * sum;
}

