double schedule_static()
{
    double total_sum = 0.0;
    int start_index = 0;
    int end_index = 0;

    // Calculate the number of threads based on the number of available cores
    int num_threads = omp_get_max_threads();

    // Calculate the range for each thread
    int chunk_size = (1000000000 + num_threads - 1) / num_threads;
    int remainder = 1000000000 % num_threads;

    // Distribute the range among threads
    for (int i = 0; i < num_threads; ++i)
    {
        if (i == num_threads - 1)
        {
            end_index = 1000000000;
        }
        else
        {
            end_index = start_index + chunk_size;
            if (i < remainder)
            {
                end_index++;
            }
        }

        // Perform the summation within each thread
        #pragma omp parallel for reduction(+:total_sum)
        for (int j = start_index; j < end_index; ++j)
        {
            total_sum += j;
        }

        // Update the start index for the next iteration
        start_index = end_index;
    }

    // Calculate the final average
    double average = total_sum / 1000000000;

    // Measure the time taken
    double start_time = omp_get_wtime();
    double end_time = omp_get_wtime();

    // Output the results
    printf("Average: %.10f\n", average);
    printf("Elapsed Time: %.6f seconds\n", end_time - start_time);

    return average;
}

